                          <Metric label="Paint mask" value={moneyOrHeld(item.supplies_cost)} />
                          <Metric label="Paint + supplies" value={moneyOrHeld(item.paint_cost)} />
                          <Metric label="Labor" value={moneyOrHeld(item.labor_cost)} />
